CREATE TABLE IF NOT EXISTS jpti_intelligence_memory(memory_id TEXT PRIMARY KEY,scope TEXT NOT NULL DEFAULT 'global',department_id TEXT,agent_id TEXT,memory_type TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,source TEXT,source_url TEXT,evidence_status TEXT NOT NULL DEFAULT 'unverified',confidence REAL NOT NULL DEFAULT .5 CHECK(confidence BETWEEN 0 AND 1),importance REAL NOT NULL DEFAULT .5 CHECK(importance BETWEEN 0 AND 1),tags_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(tags_json)),metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json)),expires_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jpti_intelligence_memory_scope_time ON jpti_intelligence_memory(scope,created_at DESC);
CREATE INDEX IF NOT EXISTS jpti_intelligence_memory_agent ON jpti_intelligence_memory(agent_id,created_at DESC);
CREATE TABLE IF NOT EXISTS jpti_intelligence_memory_edges(edge_id TEXT PRIMARY KEY,from_memory_id TEXT NOT NULL REFERENCES jpti_intelligence_memory(memory_id) ON DELETE CASCADE,to_memory_id TEXT NOT NULL REFERENCES jpti_intelligence_memory(memory_id) ON DELETE CASCADE,relation TEXT NOT NULL,weight REAL NOT NULL DEFAULT .5 CHECK(weight BETWEEN 0 AND 1),created_at TEXT NOT NULL,UNIQUE(from_memory_id,to_memory_id,relation));
CREATE TABLE IF NOT EXISTS jpti_agent_tasks(task_id TEXT PRIMARY KEY,department_id TEXT,agent_id TEXT,title TEXT NOT NULL,objective TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'queued',input_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(input_json)),result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)),error TEXT,attempts INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,started_at TEXT,completed_at TEXT);
CREATE INDEX IF NOT EXISTS jpti_agent_tasks_queue ON jpti_agent_tasks(status,priority,created_at);
CREATE TABLE IF NOT EXISTS jpti_agent_messages(message_id TEXT PRIMARY KEY,from_agent_id TEXT,to_agent_id TEXT,from_department TEXT,to_department TEXT,subject TEXT NOT NULL,body TEXT NOT NULL,message_type TEXT NOT NULL DEFAULT 'handoff',priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'unread',related_task_id TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jpti_agent_messages_inbox ON jpti_agent_messages(to_department,status,created_at DESC);
CREATE TABLE IF NOT EXISTS jpti_agent_scorecards(agent_id TEXT NOT NULL,metric_date TEXT NOT NULL,decisions INTEGER NOT NULL DEFAULT 0,correct_decisions INTEGER NOT NULL DEFAULT 0,calibrated_decisions INTEGER NOT NULL DEFAULT 0,evidence_contributions INTEGER NOT NULL DEFAULT 0,risk_violations INTEGER NOT NULL DEFAULT 0,useful_handoffs INTEGER NOT NULL DEFAULT 0,metrics_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metrics_json)),updated_at TEXT NOT NULL,PRIMARY KEY(agent_id,metric_date));
CREATE TABLE IF NOT EXISTS jpti_strategy_registry(strategy_id TEXT PRIMARY KEY,name TEXT NOT NULL,family TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'experimental',parameters_json TEXT NOT NULL CHECK(json_valid(parameters_json)),rules_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(rules_json)),parent_strategy_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,retired_at TEXT);
CREATE INDEX IF NOT EXISTS jpti_strategy_registry_status ON jpti_strategy_registry(status,updated_at DESC);
CREATE TABLE IF NOT EXISTS jpti_strategy_experiments(experiment_id TEXT PRIMARY KEY,strategy_id TEXT,symbol TEXT,timeframe TEXT,method TEXT NOT NULL,status TEXT NOT NULL,config_json TEXT NOT NULL CHECK(json_valid(config_json)),result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)),data_fingerprint TEXT,created_at TEXT NOT NULL,completed_at TEXT);
CREATE INDEX IF NOT EXISTS jpti_strategy_experiments_strategy ON jpti_strategy_experiments(strategy_id,created_at DESC);
CREATE TABLE IF NOT EXISTS jpti_risk_policies(policy_id TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jpti_risk_events(event_id TEXT PRIMARY KEY,event_type TEXT NOT NULL,severity TEXT NOT NULL,decision TEXT NOT NULL,reason TEXT NOT NULL,context_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(context_json)),acknowledged INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jpti_risk_events_time ON jpti_risk_events(created_at DESC);
CREATE TABLE IF NOT EXISTS jpti_trade_intelligence(trade_id TEXT PRIMARY KEY,agent_id TEXT,strategy_id TEXT,symbol TEXT NOT NULL,market_type TEXT,direction TEXT NOT NULL,status TEXT NOT NULL,setup_fingerprint TEXT,entry_price REAL,stop_price REAL,target_price REAL,risk_amount REAL,reward_risk REAL,regime TEXT,session_name TEXT,confidence REAL,evidence_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(evidence_json)),agent_assessments_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(agent_assessments_json)),execution_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(execution_json)),outcome_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(outcome_json)),lessons_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(lessons_json)),opened_at TEXT,closed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jpti_trade_intelligence_symbol ON jpti_trade_intelligence(symbol,created_at DESC);
CREATE INDEX IF NOT EXISTS jpti_trade_intelligence_strategy ON jpti_trade_intelligence(strategy_id,created_at DESC);
INSERT OR IGNORE INTO jpti_schema_migrations(version) VALUES ('0010_intelligence_foundation');